def read_ints():
    return list(map(int, input().split()))

def main():
    n, m, k = read_ints()
    museum = [input().strip() for _ in range(n)]
    starts = [tuple(read_ints()) for _ in range(k)]

    # Directions for moving to adjacent cells
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start_x, start_y):
        queue = [(start_x, start_y)]
        visited = set((start_x, start_y))
        pictures = 0

        while queue:
            x, y = queue.pop(0)
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    if museum[nx][ny] == '.':
                        queue.append((nx, ny))
                    elif museum[nx][ny] == '*':
                        pictures += 1
        return pictures

    results = []
    for start_x, start_y in starts:
        results.append(bfs(start_x - 1, start_y - 1))

    print('\n'.join(map(str, results)))

